package com.autoops.conversation.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="conversations")public class Conversation{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="user_id",nullable=false)private Long userId;@Column(nullable=false)private String title;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();public Long getId(){return id;}public void setUserId(Long v){userId=v;}public void setTitle(String v){title=v;}}
